import re

_TITLE_RE = re.compile(r"<title(?:\s[^>]*)?>(.*?)</title\s*>", re.IGNORECASE | re.DOTALL)


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html, or "".

    Tag matching is case-insensitive, and the opening tag may carry
    attributes. Returns "" when there is no title element or it is
    unclosed. Only the first title element is used. No network access.
    """
    m = _TITLE_RE.search(html)
    return m.group(1) if m else ""


def test_basic_title() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title</body></html>") == ""


def test_empty_string() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_title_with_attributes() -> None:
    assert title_of('<title lang="en">Attr</title>') == "Attr"


def test_unclosed_title() -> None:
    assert title_of("<title>Never closed") == ""


def test_only_first_title() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_multiline_title() -> None:
    assert title_of("<title>\n  Line one\n  line two\n</title>") == "\n  Line one\n  line two\n"


def test_surrounding_whitespace_preserved() -> None:
    assert title_of("<title>  padded  </title>") == "  padded  "


def test_does_not_match_titlelike_tags() -> None:
    assert title_of("<titles>Nope</titles>") == ""


def test_title_with_entities_left_raw() -> None:
    assert title_of("<title>A &amp; B</title>") == "A &amp; B"


def test_unicode_title() -> None:
    assert title_of("<title>Café ☕</title>") == "Café ☕"

